      { name: 'Domain', price: 1400, cycle: 'year', since: '2023-03-02' },
    ] }));
    assert.deepEqual(load(path).map((s) => s.cycle), ['monthly', 'yearly']);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});
